@push('scripts')<script>document.getElementById('tv-subject').addEventListener('change',function(){let s=this.value;document.querySelectorAll('#tv-topic option[data-subject]').forEach(o=>o.hidden=o.dataset.subject!==s);document.getElementById('tv-topic').value='';});document.getElementById('tv-subject').dispatchEvent(new Event('change'));function editTopicVideo(button){const v=JSON.parse(button.dataset.video),f=document.querySelector('form[action="{{ route('admin.topic-videos.save') }}"]');f.querySelector('[name=subject_id]').value=v.subject_id;f.querySelector('[name=subject_id]').dispatchEvent(new Event('change'));f.querySelector('[name=topic_id]').value=v.topic_id;['title','origin','video_url','description','teacher','channel_name','sort_order','status'].forEach(k=>f.querySelector('[name='+k+']').value=v[k]??'');let h=f.querySelector('[name=id]');if(!h){h=document.createElement('input');h.type='hidden';h.name='id';f.appendChild(h);}h.value=v.id;f.querySelector('[name=is_featured]').checked=!!v.is_featured;scrollTo({top:0,behavior:'smooth'});}</script>@endpush
